    referenceFiles: ["aesthetic-principles.md", "anti-patterns.md", "bespoke-vs-presets.md", "caption-grouping.md", "composition-craft.md", "direction-catalog.md", "failure-modes.md", "layout-heuristics.md", "motion-vocabulary.md", "rail.md", "reference-bar.md", "scene-types.md", "typographic-moves.md", "typography-presets.md", "references/aesthetic-principles.md", "references/anti-patterns.md", "references/bespoke-vs-presets.md", "references/caption-grouping.md", "references/composition-craft.md", "references/direction-catalog.md", "references/failure-modes.md", "references/layout-heuristics.md", "references/motion-vocabulary.md", "references/rail.md", "references/reference-bar.md", "references/scene-types.md", "references/typographic-moves.md", "references/typography-presets.md"],
    source: "https://github.com/heygen-com/hyperframes.git",
